function maxActivities(intervals) {
  // BUG: sorts by shortest duration
  const sorted = [...intervals].sort((a, b) => (a[1]-a[0]) - (b[1]-b[0]));
  let count = 0, lastEnd = -Infinity;
  for (const [start, end] of sorted) {
    if (start >= lastEnd) { count++; lastEnd = end; }
  }
  return count;
}
console.log(maxActivities([[0,4],[3,5],[4,8]]));
